grid = sorted(set(grid))
matches = all(k_eval(x) == candidate(x) for x in grid)

# Roots of k from the factorization, with multiplicities
roots = [F(0), F(1), F(1)]

if matches and c == F(1, 6):
    final_answer = "k(s) = (1/4) * s * (s - 1)**2"
