from fractions import Fraction as F

def norm(p):
    return {e: c for e, c in p.items() if c != 0}

def deriv(p):
    return norm({e - 1: c * e for e, c in p.items() if e > 0})

def mul(p, q):
    r = {}
    for e1, c1 in p.items():
        for e2, c2 in q.items():
            r[e1 + e2] = r.get(e1 + e2, F(0)) + c1 * c2
    return norm(r)

def evalp(p, x):
    return sum(c * (x ** e) for e, c in p.items())

def fmt(p):
    return " + ".join(f"({c})x^{e}" for e, c in sorted(p.items(), reverse=True))

# Exact value of c
c = F(20, -24) - (2 + -3)
print("c =", c)

# f(x) = 1/16 x^4 + 1 + 1/8 x^2 + 0*x - c x^3
f = norm({4: F(1, 16), 0: F(1), 2: F(1, 8), 1: F(0), 3: -c})

# k = f'
k = deriv(f)
print("k(x) coefficients:", fmt(k))

# Candidate factorization derived exactly: k = (1/4) x (x-1)^2
factored = mul({1: F(1, 4)}, mul({1: F(1), 0: F(-1)}, {1: F(1), 0: F(-1)}))
print("Factored form (1/4)x(x-1)^2 expands to:", fmt(factored))
print("Exact match of k with factored form:", k == factored)

# Submitted answer: (1/4)x^3 + (1/4)x + (57/24)x^2
submitted = norm({3: F(1, 4), 1: F(1, 4), 2: F(57, 24)})
print("Submitted coefficients:", fmt(submitted))
print("Exact match of k with submitted:", k == submitted)

# Coefficient-level comparison
for e in range(4):
    print(f"x^{e}: expected {k.get(e, F(0))}, submitted {submitted.get(e, F(0))}")

# Exact point checks
for x in [F(0), F(1), F(2), F(-1)]:
    print(f"x={x}: k={evalp(k, x)}, submitted={evalp(submitted, x)}, factored={evalp(factored, x)}")

if k == submitted:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
