from itertools import product

# Rules: name -> (antecedents [(atom, required_value)], (conclusion_atom, value))
RULES = {
    "R1": ([("ant_deal_stork", True), ("dalmatian_no_trade_stork", True)],
           ("stork_builds_plant", True)),
    "R2": ([("stork_builds_plant", True)], ("mouse_shouts_beetle", False)),
    "R3": ([("stork_money_gt_walrus", True)], ("stork_builds_plant", False)),
    "R4": ([("mouse_in_africa", True)], ("mouse_smiles_cobra", True)),
    "R5": ([("mouse_hugs_dinosaur", True), ("mouse_smiles_cobra", True)],
           ("mouse_shouts_beetle", True)),
    "R6": ([("llama_has_instrument", True)], ("llama_calls_husky", True)),
    "R7": ([("mouse_works_agriculture", True)], ("mouse_smiles_cobra", False)),
    "R8": ([("some_animal_photo_fish", True)], ("llama_calls_husky", False)),
}
# (winner, loser): winner overrides loser when both fire with conflicting conclusions
PREFER = {("R3", "R1"), ("R5", "R2"), ("R6", "R8"), ("R7", "R4")}

# Stated facts relevant to the rules (stork's 98 dollars and the other stated facts
# do not appear in any antecedent that could change the answer).
STATED = {"ant_deal_stork", "dalmatian_no_trade_stork", "some_animal_photo_fish"}
DERIVED = {c for _, (c, _) in RULES.values()}
FREE = sorted({a for ants, _ in RULES.values() for a, _ in ants} - STATED - DERIVED)
TARGET = "mouse_shouts_beetle"
CLAIMED = "proved"


def status(vals, ants):
    unknown = False
    for atom, need in ants:
        have = vals[atom]
        if have is None:
            unknown = True
        elif have != need:
            return "blocked"
    return "pending" if unknown else "fires"


def resolve(atom, vals, base):
    fired, pending = [], []
    for name, (ants, (concl, value)) in RULES.items():
        if concl != atom:
            continue
        s = status(vals, ants)
        if s == "fires":
            fired.append((name, value))
        elif s == "pending":
            pending.append((name, value))
    if not fired and not pending:
        return base[atom]
    if not fired:
        return None

    def defeated(name, value, group):
        return any(other_val != value and (other, name) in PREFER
                   for other, other_val in group)

    live = [(n, v) for n, v in fired if not defeated(n, v, fired)]
    values = {v for _, v in live}
    if len(values) != 1:
        return None
    v = values.pop()
    if any(w != v for _, w in pending):
        return None
    return v


def chain(base):
    vals = dict(base)
    for _ in range(20):
        new = dict(vals)
        for atom in DERIVED:
            new[atom] = resolve(atom, vals, base)
        if new == vals:
            break
        vals = new
    return vals


def verdict(v):
    if v is True:
        return "proved"
    if v is False:
        return "disproved"
    return "unknown"


# Exhaustive enumeration over every assignment of the free (unstated) atoms.
results = {}
for bits in product([True, False], repeat=len(FREE)):
    base = {a: False for a in DERIVED}
    base.update({a: True for a in STATED})
    base.update(dict(zip(FREE, bits)))
    results[tuple(zip(FREE, bits))] = chain(base)

N = len(results)
tally = {True: 0, False: 0, None: 0}
for vals in results.values():
    tally[vals[TARGET]] += 1

# Closed-world reading: unstated facts are false (standard for these rule sets).
closed_key = tuple((a, False) for a in FREE)
closed_vals = results[closed_key]
closed_verdict = verdict(closed_vals[TARGET])

# Open-world reading: the answer is settled only if it holds in every model.
if tally[True] == N:
    open_verdict = "proved"
elif tally[False] == N:
    open_verdict = "disproved"
else:
    open_verdict = "unknown"

print("free atoms:", FREE)
print("models enumerated:", N)
print("stork_builds_plant (closed world):", closed_vals["stork_builds_plant"])
print("mouse_shouts_beetle (closed world):", closed_vals[TARGET], "->", closed_verdict)
print("models with shouts True / False / None:",
      tally[True], tally[False], tally[None])
print("open-world verdict across all models:", open_verdict)
print("claimed answer:", CLAIMED)

if CLAIMED in (closed_verdict, open_verdict):
    print("CHECK PASS")
else:
    print("CHECK FAIL")
