import itertools
import json

riders = ["Reynaldo", "Seamus", "Theresa", "Yuki"]
bikes = ["F", "G", "H", "J"]


def valid_schedules():
    # Enumerate every day-1 and day-2 bijection of riders to bikes, then keep
    # the pairs that satisfy the givens plus the supposition Theresa tests J on day 1.
    out = []
    for p1 in itertools.permutations(bikes):
        d1 = dict(zip(riders, p1))
        if d1["Theresa"] != "J":
            continue
        for p2 in itertools.permutations(bikes):
            d2 = dict(zip(riders, p2))
            # Each rider tests a different bike on day 2 than on day 1.
            if any(d1[r] == d2[r] for r in riders):
                continue
            # Reynaldo cannot test F (applied to both days).
            if d1["Reynaldo"] == "F" or d2["Reynaldo"] == "F":
                continue
            # Yuki cannot test J (applied to both days).
            if d1["Yuki"] == "J" or d2["Yuki"] == "J":
                continue
            # Theresa must be a tester for H on some day.
            if "H" not in (d1["Theresa"], d2["Theresa"]):
                continue
            # Seamus tests on day 2 the bike Yuki tested on day 1.
            if d2["Seamus"] != d1["Yuki"]:
                continue
            out.append((d1, d2))
    return out


schedules = valid_schedules()

options = {
    "A": lambda d1, d2: d2["Reynaldo"] == "G",
    "B": lambda d1, d2: d1["Seamus"] == "H",
    "C": lambda d1, d2: d2["Yuki"] == "H",
    "D": lambda d1, d2: "J" in (d1["Seamus"], d2["Seamus"]),
    "E": lambda d1, d2: "G" in (d1["Theresa"], d2["Theresa"]),
}

witness_exists = {
    k: any(f(d1, d2) for d1, d2 in schedules) for k, f in options.items()
}
possible = [k for k, v in witness_exists.items() if v]

if len(possible) == 1:
    final_answer = possible[0]
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "valid_schedule_count": len(schedules),
    "option_could_be_true": witness_exists,
    "possible_options": possible,
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
