import json

# Score each option on explicit criteria for undermining the claim
# "wearing less on cold, overcast days causes arthritis".
# Criteria: 1 = directly shows skirt-wearing without arthritis (counterexample),
# 1 = shared environment controls for climate/location confounds,
# 1 = same long-term habit as Ms. Zhang, -1 = supports her claim.
options = {
    "A": {"counterexample": 1, "shared_environment": 0, "same_habit": 1, "supports_claim": 0},
    "B": {"counterexample": 0, "shared_environment": 0, "same_habit": 0, "supports_claim": 1},
    "C": {"counterexample": 1, "shared_environment": 1, "same_habit": 1, "supports_claim": 0},
    "D": {"counterexample": 0, "shared_environment": 0, "same_habit": 0, "supports_claim": 0},
}

def score(f):
    return f["counterexample"] + f["shared_environment"] + f["same_habit"] - f["supports_claim"]

