# Exhaustive finite check: each option is encoded as (premise, conclusion) over
# two predicates P and Q, each a tuple of booleans across a finite universe.
def exists(seq):
    return any(seq)

def counterexample(prem, concl, max_n=3):
    # Search universes of size 1..max_n for a model where premise holds and conclusion fails.
    for n in range(1, max_n + 1):
        for P in itertools.product([False, True], repeat=n):
            for Q in itertools.product([False, True], repeat=n):
                if prem(P, Q) and not concl(P, Q):
                    return {"universe_size": n, "P": list(map(int, P)), "Q": list(map(int, Q))}
    return None

# Original argument: Some good are not cheap; therefore some cheap are not good.
# P = good, Q = cheap. Premise: exists P and not Q. Conclusion: exists Q and not P.
orig_prem = lambda P, Q: exists(p and not q for p, q in zip(P, Q))
orig_concl = lambda P, Q: exists(q and not p for p, q in zip(P, Q))

